Now I have a complete understanding of the codebase. Let me plan the implementation:

1. **Install dependencies**: `chokidar`, `ws`, `@types/ws`
2. **Create `src/serve.ts`**: The dev server logic
   - HTTP server that serves static files from `./dist` directory
   - WebSocket server using `ws` for live reload
   - File watcher using `chokidar` on `content/` and `templates/` directories
   - On file change: rebuild, then notify connected WebSocket clients to reload
   - Inject WebSocket script into served HTML pages for auto-reload
   - Support `--port` option
3. **Modify `src/index.ts`**: Add `serve` command
4. **Add tests for the serve command**: New test file for serve functionality
5. **Run build and tests**: Ensure everything passes

Let me think about the serve implementation:

### `src/serve.ts`:

```typescript
import http from 'http';
import fs from 'fs';
import path from 'path';
import { WebSocketServer, WebSocket } from 'ws';
import chokidar from 'chokidar';
import { build } from './ssg';
import { SSGOptions } from './types';

const LIVE_RELOAD_SCRIPT = `
<script>
  (function() {
    var ws = new WebSocket('ws://' + location.host);
    ws.onmessage = function(msg) {
      if (msg.data === 'reload') {
        location.reload();
      }
    };
  })();
</script>
`;

export function serve(options: SSGOptions & { port: number }): void {
  const { contentDir, outputDir, templateDir, port } = options;

  // Initial build
  build({ contentDir, outputDir, templateDir });

  // Create HTTP server
  const server = http.createServer((req, res) => {
    let filePath = path.join(outputDir, req.url === '/' ? 'index.html' : req.url || '');

    // Serve the file
    if (fs.existsSync(filePath) && fs.statSync(filePath).isFile()) {
      const ext = path.extname(filePath);
      const contentType: Record<string, string> = {
        '.html': 'text/html',
        '.css': 'text/css',
        '.js': 'text/javascript',
        '.json': 'application/json',
        '.png': 'image/png',
